<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Terms Consent Form</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --panel: #ffffff;
        --text: #162033;
        --muted: #5c677d;
        --primary: #305cff;
        --primary-strong: #2448cc;
        --border: #d8deea;
        --error: #b42318;
        --success: #146c43;
        --shadow: 0 24px 60px rgba(22, 32, 51, 0.14);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        background:
          radial-gradient(circle at top left, rgba(48, 92, 255, 0.2), transparent 32rem),
          linear-gradient(135deg, #f9fbff 0%, var(--bg) 58%, #eef3ff 100%);
        color: var(--text);
      }

      a {
        color: var(--primary-strong);
        font-weight: 700;
        text-underline-offset: 0.18em;
      }

      a:hover {
        text-decoration-thickness: 0.16em;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-160%);
        border-radius: 999px;
        background: var(--text);
        color: #ffffff;
        padding: 0.75rem 1rem;
        font-weight: 700;
        transition: transform 160ms ease;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem;
      }

      .consent-card {
        width: min(100%, 32rem);
        border: 1px solid rgba(216, 222, 234, 0.82);
        border-radius: 1.5rem;
        background: rgba(255, 255, 255, 0.92);
        box-shadow: var(--shadow);
        padding: clamp(1.5rem, 5vw, 2.5rem);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--primary-strong);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.1em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3rem);
        line-height: 1;
        letter-spacing: -0.05em;
      }

      .intro {
        margin: 1rem 0 1.75rem;
        color: var(--muted);
        font-size: 1.03rem;
        line-height: 1.6;
      }

      .required-note {
        margin: 0 0 1rem;
        color: var(--muted);
        font-size: 0.94rem;
      }

      .required-marker {
        color: var(--error);
        font-weight: 800;
      }

      .form-field {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.75rem 0.85rem;
        align-items: start;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: #fbfcff;
        padding: 1rem;
      }

      .form-field:focus-within {
        border-color: var(--primary);
        box-shadow: 0 0 0 4px rgba(48, 92, 255, 0.16);
      }

      input[type="checkbox"] {
        width: 1.3rem;
        height: 1.3rem;
        margin: 0.12rem 0 0;
        accent-color: var(--primary);
        cursor: pointer;
      }

      input[type="checkbox"]:focus-visible,
      button:focus-visible,
      a:focus-visible {
        outline: 3px solid var(--primary);
        outline-offset: 3px;
      }

      label {
        color: var(--text);
        font-weight: 750;
        line-height: 1.45;
      }

      .field-copy {
        min-width: 0;
      }

      .helper-text,
      .error-text,
      .status-message {
        margin: 0.45rem 0 0;
        font-size: 0.94rem;
        line-height: 1.5;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-text {
        color: var(--error);
        font-weight: 700;
      }

      .status-message {
        color: var(--success);
        font-weight: 700;
      }

      [hidden] {
        display: none;
      }

      .actions {
        display: flex;
        margin-top: 1.25rem;
      }

      button {
        width: 100%;
        min-height: 3rem;
        border: 0;
        border-radius: 999px;
        background: var(--primary);
        color: #ffffff;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        letter-spacing: -0.01em;
        box-shadow: 0 14px 28px rgba(48, 92, 255, 0.26);
      }

      button:hover {
        background: var(--primary-strong);
      }

      button:active {
        transform: translateY(1px);
      }

      @media (forced-colors: active) {
        .consent-card,
        .form-field,
        button {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        button {
          background: ButtonFace;
          color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const termsLink = '<a href="#terms">terms of use</a>';

      function ConsentCheckbox() {
        return `
          <div class="form-field">
            <input
              id="agree-terms"
              name="agreeTerms"
              type="checkbox"
              required
              aria-describedby="agree-terms-help agree-terms-error"
            >
            <div class="field-copy">
              <label for="agree-terms">
                I agree to the ${termsLink} <span class="required-marker" aria-hidden="true">*</span>
              </label>
              <p id="agree-terms-help" class="helper-text">
                Required to create your account and continue.
              </p>
              <p id="agree-terms-error" class="error-text" hidden>
                Error: Agree to the terms of use before continuing.
              </p>
            </div>
          </div>
        `;
      }

      function ConsentForm() {
        return `
          <form id="consent-form" novalidate>
            <p class="required-note">
              <span class="required-marker" aria-hidden="true">*</span> indicates a required field.
            </p>
            ${ConsentCheckbox()}
            <div class="actions">
              <button type="submit">Agree and continue</button>
            </div>
            <p id="form-status" class="status-message" aria-live="polite" hidden>
              Thanks. Your agreement has been recorded.
            </p>
          </form>
        `;
      }

      function App() {
        return `
          <main id="main-content" class="page-shell">
            <section class="consent-card" aria-labelledby="page-title">
              <p class="eyebrow">Account setup</p>
              <h1 id="page-title">Review and agree</h1>
              <p class="intro">
                Confirm your consent to the terms before moving on to your product workspace.
              </p>
              ${ConsentForm()}
            </section>
          </main>
        `;
      }

      document.getElementById("root").innerHTML = App();

      const form = document.getElementById("consent-form");
      const checkbox = document.getElementById("agree-terms");
      const error = document.getElementById("agree-terms-error");
      const status = document.getElementById("form-status");

      function setCheckboxValidity() {
        const isValid = checkbox.checked;
        checkbox.setAttribute("aria-invalid", String(!isValid));
        error.hidden = isValid;
        status.hidden = true;
        return isValid;
      }

      checkbox.addEventListener("change", setCheckboxValidity);

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!setCheckboxValidity()) {
          checkbox.focus();
          return;
        }

        status.hidden = false;
      });
    </script>
  </body>
</html>
