     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="root"></div>

     <script>
       const termsLink = '<a href="#terms">terms of use</a>';

       function ConsentCheckbox() {
         return `
           <div class="form-field">
             <input
               id="agree-terms"
               name="agreeTerms"
               type="checkbox"
               required
               aria-describedby="agree-terms-help agree-terms-error"
             >
             <div class="field-copy">
               <label for="agree-terms">
                 I agree to the ${termsLink} <span class="required-marker" aria-hidden="true">*</span>
               </label>
               <p id="agree-terms-help" class="helper-text">
                 Required to create your account and continue.
               </p>
               <p id="agree-terms-error" class="error-text" hidden>
                 Error: Agree to the terms of use before continuing.
               </p>
             </div>
           </div>
         `;
       }

       function ConsentForm() {
         return `
           <form id="consent-form" novalidate>
             <p class="required-note">
               <span class="required-marker" aria-hidden="true">*</span> indicates a required field.
             </p>
             ${ConsentCheckbox()}
             <div class="actions">
               <button type="submit">Agree and continue</button>
             </div>
             <p id="form-status" class="status-message" aria-live="polite" hidden>
               Thanks. Your agreement has been recorded.
             </p>
           </form>
         `;
       }

       function App() {
         return `
           <main id="main-content" class="page-shell">
             <section class="consent-card" aria-labelledby="page-title">
               <p class="eyebrow">Account setup</p>
               <h1 id="page-title">Review and agree</h1>
               <p class="intro">
                 Confirm your consent to the terms before moving on to your product workspace.
               </p>
               ${ConsentForm()}
             </section>
           </main>
         `;
       }

       document.getElementById("root").innerHTML = App();

       const form = document.getElementById("consent-form");
       const checkbox = document.getElementById("agree-terms");
       const error = document.getElementById("agree-terms-error");
       const status = document.getElementById("form-status");

       function setCheckboxValidity() {
         const isValid = checkbox.checked;
         checkbox.setAttribute("aria-invalid", String(!isValid));
         error.hidden = isValid;
         status.hidden = true;
         return isValid;
       }

       checkbox.addEventListener("change", setCheckboxValidity);

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         if (!setCheckboxValidity()) {
           checkbox.focus();
           return;
         }

         status.hidden = false;
       });
     </script>
   </body>
